import pub.developers.forum.api.request.user.UserUpdateInfoRequest;
import pub.developers.forum.app.support.LoginUserContext;
import pub.developers.forum.domain.entity.User;
import pub.developers.forum.domain.repository.UserRepository;

import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
public class UserManagerTest {

    @Mock
    private UserRepository userRepository;

    @Mock
    private LoginUserContext loginUserContext;

    @InjectMocks
    private UserManager userManager;

    private User testUser;
    private String userEmail = "test@example.com";

    @BeforeEach
    void setUp() {
        testUser = new User();
        testUser.setId(1L);
        testUser.setEmail(userEmail);
    }

    @Test
    void updateInfo_success() {
        UserUpdateInfoRequest request = UserUpdateInfoRequest.builder()
                .email(userEmail)
                .nickname("NewNickname")
                .signature("NewSignature")
                .build();

        when(loginUserContext.getUser()).thenReturn(testUser);
        when(userRepository.getByEmail(request.getEmail())).thenReturn(null);

        userManager.updateInfo(request);

        verify(loginUserContext, times(1)).getUser();
        verify(userRepository, times(1)).getByEmail(request.getEmail());
        verify(userRepository, times(1)).update(any(User.class));
    }

    @Test
    void updateInfo_fail_whenUserEmailExists() {
        UserUpdateInfoRequest request = UserUpdateInfoRequest.builder()
                .email("another@example.com")
                .nickname("NewNickname")
                .signature("NewSignature")
                .build();

        User existingUser = new User();
        existingUser.setId(2L);
        existingUser.setEmail(request.getEmail());

        when(loginUserContext.getUser()).thenReturn(testUser);
        when(userRepository.getByEmail(request.getEmail())).thenReturn(existingUser);

        assertThrows(RuntimeException.class, () -> {
            userManager.updateInfo(request);
        });

        verify(userRepository, never()).update(any(User.class));
    }
}

