@ExtendWith(MockitoExtension.class)
public class LoginUserAspectTest {

    @Mock
    private CacheService cacheService;

    @Mock
    private HttpServletRequest httpServletRequest;

    @Mock
    private ProceedingJoinPoint proceedingJoinPoint;

    @InjectMocks
    private LoginUserAspect loginUserAspect;

    @BeforeEach
    public void setUp() {
        // Mock the static method ObjectUtils.isEmpty
        mockStatic(ObjectUtils.class);
    }

    @Test
    public void testInvokeWithValidToken() throws Throwable {
        // Arrange
        String token = "validToken";
        String cacheString = "{\"id\":1,\"username\":\"testUser\"}";
        User user = JSON.parseObject(cacheString, User.class);

        when(httpServletRequest.getHeader(any(String.class))).thenReturn(token);
        when(cacheService.get(eq(CacheBizTypeEn.USER_LOGIN_TOKEN), eq(token))).thenReturn(cacheString);
        doReturn(user).when(proceedingJoinPoint).proceed();

        // Act
        Object result = loginUserAspect.invoke(proceedingJoinPoint);

        // Assert
        assertNotNull(result);
        verify(cacheService).get(eq(CacheBizTypeEn.USER_LOGIN_TOKEN), eq(token));
        verify(proceedingJoinPoint).proceed();
    }

    @Test
    public void testInvokeWithInvalidToken() throws Throwable {
        // Arrange
        String token = "invalidToken";
        when(httpServletRequest.getHeader(any(String.class))).thenReturn(token);
        when(cacheService.get(eq(CacheBizTypeEn.USER_LOGIN_TOKEN), eq(token))).thenReturn(null);

        // Act
        Object result = loginUserAspect.invoke(proceedingJoinPoint);

        // Assert
        assertNotNull(result);
        verify(cacheService).get(eq(CacheBizTypeEn.USER_LOGIN_TOKEN), eq(token));
        verify(proceedingJoinPoint, never()).proceed();
    }

